// The crop catalogue: what the tool knows about each crop before anything is planned.
// Source of truth: backend/supabase/seed/catalog_v1.json, loaded into the database by a migration
// (generated by scripts/gen-catalog-sql.mjs; a test checks the two never drift apart).
// A null value means "missing data", never zero: the tool shows it as missing.
import catalogJson from '../../../backend/supabase/seed/catalog_v1.json';
import { addMonths, isDate, monthDayLabel, type DateStr } from './dates';

export type Range = { min: number; max: number };
export type Space = 'indoor' | 'outdoor';
export type Scale = 'm2' | 'capi';
/** monthly: per month from the first income · cycle: per production cycle · yearly: once a year */
export type Income =
  | { kind: 'monthly'; min: number; max: number }
  | { kind: 'yearly'; min: number; max: number }
  | { kind: 'cycle'; min: number; max: number; cycleDays: Range };
/** "MM-DD" to "MM-DD", both included; from > to crosses the new year (October to March). */
export type Window = { from: string; to: string };
export type TaskTemplate = { title: string; offsetDays: number; everyDays: number | null };

export type Crop = {
  id: string;
  name: string;
  space: Space;
  /** what income, budget and hours grow with: square metres or animals */
  scale: Scale;
  /** the quantity (m² or animals) the schema's numbers refer to */
  refQty: number;
  /** recommended minimum area; below it the tool warns, it does not refuse */
  minM2: number | null;
  /** for animals: recommended m² per head */
  m2PerHead: number | null;
  windows: Window[];
  firstIncomeDays: Range;
  income: Income | null;
  /** initial investment for budget.refQty units */
  budget: (Range & { refQty: number }) | null;
  recurringMonthly: Range | null;
  hoursPerWeek: Range | null;
  /** Produzione Standard (for the young-farmer grant): value per `per` units */
  ps: { value: number; per: number; unit: 'm2' | 'capo'; source: string } | null;
  channels: string[];
  priceNote: string;
  salesCycle: string;
  tasks: TaskTemplate[];
  sources: { data: string; windows: string; tasks: string };
  notes: string[];
};
export type Catalog = Crop[];

export const SPACE_LABEL: Record<Space, string> = { indoor: 'Interno', outdoor: 'Esterno' };
export const scaleUnit = (c: Pick<Crop, 'scale'>) => (c.scale === 'capi' ? 'capi' : 'm²');

const MD = /^(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const isRange = (r: unknown): r is Range => !!r && typeof (r as Range).min === 'number' && typeof (r as Range).max === 'number' && (r as Range).min <= (r as Range).max && (r as Range).min >= 0;

/** Problems with a catalogue entry, in Italian; empty when it is usable. */
export function validateCrop(c: Crop): string[] {
  const p: string[] = [];
  if (!/^[a-z0-9][a-z0-9-]{0,49}$/.test(c.id)) p.push(`id non valido: ${c.id}`);
  if (!c.name?.trim()) p.push(`${c.id}: manca il nome`);
  if (c.space !== 'indoor' && c.space !== 'outdoor') p.push(`${c.id}: spazio sconosciuto`);
  if (c.scale !== 'm2' && c.scale !== 'capi') p.push(`${c.id}: scala sconosciuta`);
  if (!(c.refQty > 0)) p.push(`${c.id}: quantità di riferimento mancante`);
  if (!c.windows.length || c.windows.some((w) => !MD.test(w.from) || !MD.test(w.to))) p.push(`${c.id}: finestra di avvio non valida`);
  if (!isRange(c.firstIncomeDays)) p.push(`${c.id}: giorni al primo ricavo non validi`);
  if (c.income && !isRange(c.income)) p.push(`${c.id}: ricavo non valido`);
  if (c.income?.kind === 'cycle' && !(isRange(c.income.cycleDays) && c.income.cycleDays.min > 0)) p.push(`${c.id}: durata del ciclo non valida`);
  if (c.budget && !(isRange(c.budget) && c.budget.refQty > 0)) p.push(`${c.id}: budget non valido`);
  if (c.recurringMonthly && !isRange(c.recurringMonthly)) p.push(`${c.id}: costi ricorrenti non validi`);
  if (c.hoursPerWeek && !isRange(c.hoursPerWeek)) p.push(`${c.id}: ore non valide`);
  if (c.scale === 'capi' && !(c.m2PerHead && c.m2PerHead > 0)) p.push(`${c.id}: mancano i m² per capo`);
  if (c.tasks.some((t) => !t.title.trim() || t.offsetDays < 0 || (t.everyDays !== null && t.everyDays < 1))) p.push(`${c.id}: task del ciclo non validi`);
  return p;
}

export const CATALOG: Catalog = (catalogJson as unknown as { crops: Crop[] }).crops;

export const cropById = (catalog: Catalog, id: string) => catalog.find((c) => c.id === id);

// --- start windows -----------------------------------------------------------------------

const md = (d: DateStr) => d.slice(5);
const covers = (w: Window, d: DateStr) => (w.from <= w.to ? md(d) >= w.from && md(d) <= w.to : md(d) >= w.from || md(d) <= w.to);

/** True when a crop may start on this date. */
export function inWindow(windows: Window[], d: DateStr): boolean {
  return isDate(d) && windows.some((w) => covers(w, d));
}

export const isAllYear = (w: Window[]) => w.some((x) => x.from === '01-01' && x.to === '12-31');

export function windowLabel(windows: Window[]): string {
  if (isAllYear(windows)) return "Tutto l'anno";
  return windows.map((w) => `${monthDayLabel(w.from)} – ${monthDayLabel(w.to)}`).join(' · ');
}

/** Real date ranges for the date picker: one per window per year, clipped to [from, to]. */
export type WindowOption = { min: DateStr; max: DateStr; label: string };
export function windowOptions(windows: Window[], from: DateStr, to: DateStr): WindowOption[] {
  if (isAllYear(windows)) return [{ min: from, max: to, label: "Tutto l'anno" }];
  const out: WindowOption[] = [];
  const y0 = Number(from.slice(0, 4)) - 1, y1 = Number(to.slice(0, 4));
  for (let y = y0; y <= y1; y++) {
    for (const w of windows) {
      const start = `${y}-${w.from}`;
      const end = w.from <= w.to ? `${y}-${w.to}` : `${y + 1}-${w.to}`;
      const min = start < from ? from : start, max = end > to ? to : end;
      if (!isDate(min) || !isDate(max) || min > max) continue;
      const yearLabel = start.slice(0, 4) === end.slice(0, 4) ? start.slice(0, 4) : `${start.slice(0, 4)}/${end.slice(2, 4)}`;
      out.push({ min, max, label: `${monthDayLabel(w.from)} – ${monthDayLabel(w.to)} ${yearLabel}` });
    }
  }
  return out.sort((a, b) => (a.min < b.min ? -1 : 1));
}

/** The range of start dates the form offers: two years back (crops already running) to three years ahead. */
export function startRange(today: DateStr): { from: DateStr; to: DateStr } {
  return { from: addMonths(today, -24), to: addMonths(today, 36) };
}
